from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The dominant line color is the divider; the most common other color
    # is the background.
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    wall = max((v for v in counts if v != bg), key=lambda v: counts[v])

    wall_cells = {(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == wall}
    if not wall_cells:
        return out

    # Corner-pattern components provide the colors that propagate along
    # adjacent divider lines.
    sources = {}
    for sr, sc in ((0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)):
        if grid[sr][sc] == wall:
            continue
        q = deque([(sr, sc)])
        seen = {(sr, sc)}
        vals = Counter()
        while q:
            r, c = q.popleft()
            vals[grid[r][c]] += 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if (0 <= rr < h and 0 <= cc < w and
                    grid[rr][cc] != wall and (rr, cc) not in seen):
                    seen.add((rr, cc))
                    q.append((rr, cc))

        candidates = [(n, color) for color, n in vals.items()
                      if color not in (wall, bg)]
        if not candidates:
            continue
        color = max(candidates)[1]
        for r, c in seen:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if (rr, cc) in wall_cells:
                    sources.setdefault(color, set()).add((rr, cc))

    # Propagate each corner color over the connected divider network.
    distances = {}
    for color, starts in sources.items():
        dist = {p: 0 for p in starts}
        q = deque(starts)
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in wall_cells and p not in dist:
                    dist[p] = dist[(r, c)] + 1
                    q.append(p)
        distances[color] = dist

    for r, c in wall_cells:
        ranked = sorted((d.get((r, c), 10**9), color)
                        for color, d in distances.items())
        if ranked and (len(ranked) == 1 or ranked[0][0] < ranked[1][0]):
            out[r][c] = ranked[0][1]
    return out
