            (12, 12, 16, 16),
        ]
        starts = {}
        for r0, c0, r1, c1 in boxes:
            motif = Counter(grid[r][c]
                            for r in range(r0, r1)
                            for c in range(c0, c1)
                            if grid[r][c] not in (wall, background))
            if not motif:
                continue
            color = motif.most_common(1)[0][0]
            seeds = {(r, c) for r in range(r0, r1)
                     for c in range(c0, c1) if (r, c) in walls}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        p = (r + dr, c + dc)
                        if p in walls:
                            seeds.add(p)
            starts.setdefault(color, set()).update(seeds)

        # Propagate each motif's color along the connected divider.
        distances = {}
        for color, seeds in starts.items():
            dist = {p: 0 for p in seeds}
            q = deque(seeds)
            while q:
                r, c = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (r + dr, c + dc)
                    if p in walls and p not in dist:
                        dist[p] = dist[(r, c)] + 1
                        q.append(p)
            distances[color] = dist

        for p in walls:
            choices = [(d.get(p, 10**9), color)
                       for color, d in distances.items()]
            if choices:
                # Resolve equal-distance ties in favor of the more common source.
                best = min(d for d, _ in choices)
                tied = [color for d, color in choices if d == best]
                out[p[0]][p[1]] = 5 if 5 in tied else tied[0]
        return out

